using System;
using System.IO;
using System.Drawing;
using System.Drawing.Drawing2D;
using System.Collections.Generic;
using System.Windows.Forms;
using System.Web.Script.Serialization;

static class UiPreferences {
 public static bool Light {get;private set;}public static bool English {get;private set;}
 static DateTime last,stamp;static bool installed;
 static readonly Dictionary<string,string> texts=new Dictionary<string,string>{
  {"PhoneDeck · Voz e Áudio","PhoneDeck · Voice & Audio"},{"PhoneDeck · Gravação","PhoneDeck · Recording"},{"Voz e Áudio","Voice & Audio"},{"CONFIGURAÇÕES","SETTINGS"},{"Configurações","Settings"},{"Microfone","Microphone"},{"Caixinha / saída de áudio","Speaker / audio output"},{"Silenciar microfone","Mute microphone"},{"Ativar microfone","Unmute microphone"},{"Aplicar","Apply"},{"Fechar","Close"},{"Verificar microfone (6 s)","Check microphone (6 s)"},{"Parar verificação","Stop check"},{"PROCESSAMENTO DE VOZ","VOICE PROCESSING"},{"Configurar redução de ruído","Configure noise suppression"},{"PROCESSAMENTO","PROCESSING"},{"Redução de ruído","Noise suppression"},{"Origem do microfone","Microphone source"},{"Intensidade","Strength"},{"Gravação","Recording"},{"Gravar conversa","Record conversation"},{"Gravação manual","Manual recording"},{"Gravando conversa","Recording conversation"},{"Iniciando gravação…","Starting recording…"},{"Conversa salva","Conversation saved"},{"Gravar","Record"},{"Parar e salvar","Stop and save"},{"Pasta","Folder"},{"Microfone + som da saída escolhida","Microphone + selected output audio"},{"Fale para ver o nível. Sem gravação ou reprodução.","Speak to see the level. Nothing is saved or played."},{"Ligar","Call"},{"Atender","Answer"},{"Desligar","Hang up"},{"Todos","All"},{"Favoritos","Favorites"},{"CONTATOS","CONTACTS"},{"Central de chamadas","Call center"},{"CHAMADAS RECENTES","RECENT CALLS"},{"DISCAGEM RÁPIDA","QUICK DIAL"},{"Discar número","Dial number"},{"ÁUDIO","AUDIO"},{"Atualizar","Refresh"},{"Escolha um contato","Choose a contact"},{"Seu celular","Your phone"},{"Celular Bluetooth","Bluetooth phone"},{"Pronto para seus comandos.","Ready for your commands."},{"Aguardando leitura","Waiting for status"},{"Verificando…","Checking…"},{"TERMINAL DE CHAMADAS","CALL TERMINAL"},{"Conectar celular · QR","Connect phone · QR"},{"Adicionar contato","Add contact"},{"Nome","Name"},{"Telefone com DDD","Phone number with area code"},{"Salvar contato","Save contact"},{"Seleciona os dispositivos de comunicação do Windows. Nenhuma chamada é iniciada.","Selects Windows communication devices. No call is started."},{"Entrada RTX Voice disponível na lista de microfones.","RTX Voice input is available in the microphone list."},{"Componente de redução de ruído ainda não instalado.","Noise suppression component is not installed."},{"Redução de ruído: use uma entrada de microfone processada (RTX Voice).","Noise suppression: select a processed microphone input (RTX Voice)."},{"Sinal do microfone detectado. O teste não verifica a voz recebida pelo telefone.","Microphone signal detected. This does not verify audio received by the phone."},{"Sem sinal detectado. Confira o mudo e o nível físico do ME6S. Nenhuma chamada feita.","No signal detected. Check the ME6S hardware mute and level. No call was made."},{"Salvo. Mudo sincronizado com o transporte da chamada.","Saved. Mute synchronized with the call transport."},{"Salvo. O mudo será sincronizado ao preparar a próxima chamada.","Saved. Mute will synchronize when preparing the next call."},{"Seleção pendente. Aplicar salva os dispositivos e o nível escolhido.","Selection pending. Apply saves the devices and selected level."}
 };
 static string PathName {get{return Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"preferences.local.json");}}
 static UiPreferences(){Reload();}
 static void Reload(){try{if(File.Exists(PathName)){var written=File.GetLastWriteTimeUtc(PathName);if(written==stamp)return;var values=new JavaScriptSerializer().Deserialize<Dictionary<string,string>>(File.ReadAllText(PathName));Light=values.ContainsKey("on-tema")&&values["on-tema"]=="claro";English=values.ContainsKey("on-idioma")&&values["on-idioma"]=="en";stamp=written;}}catch{}}
 public static string T(string pt,string en){return English?en:pt;}
 public static string Translate(string text){if(String.IsNullOrEmpty(text))return text;if(English){string value;if(texts.TryGetValue(text,out value))return value;return text.Replace("Intensidade:","Strength:").Replace("Nível do microfone:","Microphone level:").Replace("Volume geral","Master volume").Replace("●  Microfone silenciado","●  Microphone muted").Replace("●  Microfone ligado","●  Microphone on");}foreach(var item in texts)if(item.Value==text)return item.Key;return text.Replace("Strength:","Intensidade:").Replace("Microphone level:","Nível do microfone:").Replace("Master volume","Volume geral").Replace("●  Microphone muted","●  Microfone silenciado").Replace("●  Microphone on","●  Microfone ligado");}
 public static void Set(bool light,bool english,bool save=true){Light=light;English=english;if(save)try{File.WriteAllText(PathName,new JavaScriptSerializer().Serialize(new Dictionary<string,string>{{"on-tema",light?"claro":"escuro"},{"on-idioma",english?"en":"pt"}}));}catch{}foreach(Form form in Application.OpenForms){Apply(form);form.Invalidate(true);}}
 public static void Install(){if(installed)return;installed=true;Application.Idle+=(s,e)=>{if((DateTime.UtcNow-last).TotalMilliseconds<750)return;last=DateTime.UtcNow;bool wasLight=Light,wasEnglish=English;Reload();foreach(Form form in Application.OpenForms){Apply(form);if(wasLight!=Light||wasEnglish!=English)form.Invalidate(true);}};}
 static Color Map(Color value){if(value.A==0)return value;int[] dark={0x0d1117,0x141a23,0x1c2430,0x273140,0xe8eef6,0x8597ae};Color[] colors={DeckTheme.Bg,DeckTheme.Surface,DeckTheme.Raised,DeckTheme.Line,DeckTheme.Text,DeckTheme.Dim};int[] light={0xf4f6f9,0xffffff,0xe9eef5,0xcbd5e1,0x162033,0x52647c};for(int i=0;i<dark.Length;i++)if((value.ToArgb()&0xffffff)==dark[i]||(value.ToArgb()&0xffffff)==light[i])return colors[i];return value;}
 public static void Apply(Control control){ScrollChrome.Apply(control);if(control.Name=="PreferenceLanguage"){control.Text=English?"BR PT":"US EN";control.AccessibleName=T("Mudar para inglês","Switch to Portuguese");}control.BackColor=Map(control.BackColor);control.ForeColor=Map(control.ForeColor);if(!(control is TextBoxBase)&&!(control is ComboBox)&&!(control is ListBox))control.Text=Translate(control.Text);var button=control as DeckButton;if(button!=null){button.Fill=Map(button.Fill);button.Ink=Map(button.Ink);if(button.Fill==DeckTheme.Blue||button.Fill==DeckTheme.Green||button.Fill==DeckTheme.Red)button.Ink=Color.White;}var children=new Control[control.Controls.Count];control.Controls.CopyTo(children,0);foreach(Control child in children)Apply(child);}
 public static Control Controls(){var panel=new FlowLayoutPanel{Width=112,Height=56,Padding=new Padding(0,6,0,0),Margin=new Padding(0),BackColor=Color.Transparent};var language=new DeckButton{Name="PreferenceLanguage",Width=62,Height=44,Ghost=true,Font=new Font("Segoe UI Semibold",9),Text=English?"BR PT":"US EN",Margin=new Padding(0,0,4,0)};var theme=new ThemePreferenceButton{Name="PreferenceTheme",Width=44,Height=44,Margin=new Padding(0)};language.Click+=(s,e)=>{Set(Light,!English);language.Text=English?"BR PT":"US EN";theme.Invalidate();};theme.Click+=(s,e)=>{Set(!Light,English);theme.Invalidate();};panel.Controls.Add(language);panel.Controls.Add(theme);return panel;}
}

sealed class ThemePreferenceButton:DeckIconButton {
 protected override void OnPaint(PaintEventArgs e){IconName=UiPreferences.Light?"moon":"sun";AccessibleName=UiPreferences.Light?UiPreferences.T("Tema escuro","Dark theme"):UiPreferences.T("Tema claro","Light theme");base.OnPaint(e);}
}
sealed class DeckComboBox:ComboBox {
 public DeckComboBox(){DrawMode=DrawMode.OwnerDrawFixed;DropDownStyle=ComboBoxStyle.DropDownList;FlatStyle=FlatStyle.Flat;ItemHeight=26;Font=new Font("Segoe UI",10);}
 protected override void OnResize(EventArgs e){base.OnResize(e);if(Width<2||Height<2)return;var old=Region;using(var path=DeckTheme.Round(new Rectangle(0,0,Width,Height),6))Region=new Region(path);if(old!=null)old.Dispose();}
 protected override void OnDrawItem(DrawItemEventArgs e){bool selected=(e.State&DrawItemState.Selected)!=0&&(e.State&DrawItemState.ComboBoxEdit)==0;using(var brush=new SolidBrush(selected?Color.FromArgb(33,86,116):DeckTheme.Raised))e.Graphics.FillRectangle(brush,e.Bounds);if(e.Index>=0)TextRenderer.DrawText(e.Graphics,GetItemText(Items[e.Index]),Font,e.Bounds,selected?Color.White:DeckTheme.Text,TextFormatFlags.Left|TextFormatFlags.VerticalCenter|TextFormatFlags.EndEllipsis|TextFormatFlags.NoPrefix);}
 protected override void WndProc(ref Message m){base.WndProc(ref m);if(!IsHandleCreated)return;if(m.Msg==0xf||m.Msg==0x85){using(var g=Graphics.FromHwnd(Handle))Chrome(g);}else if((m.Msg==0x317||m.Msg==0x318)&&m.WParam!=IntPtr.Zero){using(var g=Graphics.FromHdc(m.WParam))Chrome(g);}}
 void Chrome(Graphics g){g.SmoothingMode=SmoothingMode.AntiAlias;using(var fill=new SolidBrush(DeckTheme.Raised))g.FillRectangle(fill,ClientRectangle);using(var path=DeckTheme.Round(new Rectangle(0,0,Width-1,Height-1),5))using(var pen=new Pen(DeckTheme.Line))g.DrawPath(pen,path);int width=SystemInformation.VerticalScrollBarWidth+10;if(Focused&&ShowFocusCues)ControlPaint.DrawFocusRectangle(g,new Rectangle(6,5,Math.Max(1,Width-width-10),Math.Max(1,Height-10)),DeckTheme.Dim,DeckTheme.Raised);TextRenderer.DrawText(g,SelectedIndex<0?"":GetItemText(SelectedItem),Font,new Rectangle(9,0,Width-width-10,Height),DeckTheme.Text,TextFormatFlags.Left|TextFormatFlags.VerticalCenter|TextFormatFlags.EndEllipsis|TextFormatFlags.NoPrefix);using(var arrow=new Pen(DeckTheme.Dim,1.4f)){int x=Width-width/2,y=Height/2;g.DrawLines(arrow,new[]{new Point(x-3,y-1),new Point(x,y+2),new Point(x+3,y-1)});}}
}

sealed class DeckMeter:Control {
 int value;public int Minimum {get;set;}public int Maximum {get;set;}
 public int Value {get{return value;}set{this.value=Math.Max(Minimum,Math.Min(Maximum,value));Invalidate();}}
 public DeckMeter(){Maximum=100;DoubleBuffered=true;}
 protected override void OnPaint(PaintEventArgs e){e.Graphics.Clear(DeckTheme.Raised);using(var fill=new SolidBrush(DeckTheme.Green))e.Graphics.FillRectangle(fill,1,1,Math.Max(0,(Width-2)*Value/Math.Max(1,Maximum-Minimum)),Math.Max(1,Height-2));using(var pen=new Pen(DeckTheme.Line))e.Graphics.DrawRectangle(pen,0,0,Width-1,Height-1);}
}
